package com.hms.imports;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="import_jobs") public class ImportJob { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ImportType importType; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ImportJobStatus status; @Column(nullable=false) private int totalRows; @Column(nullable=false) private int importedRows; @Column(nullable=false) private int skippedRows; @Column(length=12000) private String errorReport; @Column(nullable=false) private OffsetDateTime createdAt; private OffsetDateTime completedAt; protected ImportJob(){} public ImportJob(UUID tenantId,ImportType type,int total,int imported,int skipped,String errors){this.id=UUID.randomUUID();this.tenantId=tenantId;this.importType=type;this.totalRows=total;this.importedRows=imported;this.skippedRows=skipped;this.errorReport=errors;this.status=errors==null||errors.isBlank()?ImportJobStatus.COMPLETED:ImportJobStatus.COMPLETED_WITH_ERRORS;this.createdAt=OffsetDateTime.now();this.completedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public ImportType getImportType(){return importType;} public ImportJobStatus getStatus(){return status;} public int getTotalRows(){return totalRows;} public int getImportedRows(){return importedRows;} public int getSkippedRows(){return skippedRows;} public String getErrorReport(){return errorReport;} public OffsetDateTime getCreatedAt(){return createdAt;} }
